<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { SearchSettingsSchema, SearchStatusSchema } from '../../../../typescript/packages/contracts/src/search';
import { runtimeRequest } from '../../api/typescript';
import { useUnsavedDraft } from '../../composables/unsaved';
const settings = ref(SearchSettingsSchema.parse({})); const configured = ref(false); const error = ref(''); const notice = ref(''); const busy = ref(false); const loaded = ref(false);
const { dirty, markSaved, confirmDiscard } = useUnsavedDraft('网络搜索配置', () => settings.value);
async function load() { if (busy.value || !confirmDiscard()) return; busy.value = true; error.value = ''; try { const result = await runtimeRequest('search', SearchStatusSchema); settings.value = result.settings; configured.value = result.credentialConfigured; loaded.value = true; markSaved(); notice.value = '已载入服务器保存的搜索配置。'; } catch (e) { error.value = e instanceof Error ? e.message : String(e); } finally { busy.value = false; } }
async function save() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { const { revision, ...configuration } = settings.value; const result = await runtimeRequest('search', SearchStatusSchema, { ...configuration, expectedRevision: revision }, 'PUT'); settings.value = result.settings; configured.value = result.credentialConfigured; markSaved(); notice.value = '搜索配置已保存，新调用立即生效。'; } catch (e) { error.value = e instanceof Error ? e.message : String(e); } finally { busy.value = false; } }
function providerChanged() { if (settings.value.provider === 'tavily') { settings.value.apiBase = 'https://api.tavily.com'; settings.value.apiKeyEnv = 'TAVILY_API_KEY'; settings.value.maxCount = Math.min(20, settings.value.maxCount); settings.value.defaultCount = Math.min(20, settings.value.defaultCount); } else if (settings.value.provider === 'brave') { settings.value.apiBase = 'https://api.search.brave.com'; settings.value.apiKeyEnv = 'BRAVE_SEARCH_API_KEY'; settings.value.maxCount = Math.min(20, settings.value.maxCount); settings.value.defaultCount = Math.min(20, settings.value.defaultCount); } else { settings.value.apiBase = 'https://api.deepseek.com'; settings.value.apiKeyEnv = 'DEEPSEEK_SEARCH_API_KEY'; } }
onMounted(load);
</script>
<template><section class="ts-fields"><div class="section-title"><div><h2>网络搜索</h2><p>与聊天模型独立配置，适用于所有支持工具调用的 Agent。</p></div><button :disabled="busy" @click="load">重新载入</button></div><p v-if="error" role="alert" class="error-banner">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form v-if="loaded" class="card ts-fields" @submit.prevent="save"><p class="muted" role="status">独立保存 · {{ dirty ? '有未保存修改' : '已与服务器同步' }}。保存后新调用立即生效。</p><fieldset :disabled="busy" class="search-fields"><label class="ts-check"><input v-model="settings.enabled" type="checkbox">启用网络搜索</label><div class="ts-form-grid"><label>搜索服务<select v-model="settings.provider" @change="providerChanged"><option value="deepseek">DeepSeek Search / Fetch</option><option value="tavily">Tavily Search / Extract</option><option value="brave">Brave Search（搜索）</option></select></label><label>API 地址<input v-model="settings.apiBase" required type="url"></label><label>密钥引用<input v-model="settings.apiKeyEnv" pattern="[A-Z_][A-Z0-9_]*" required></label><label>超时（毫秒）<input v-model.number="settings.timeoutMs" type="number" min="1000" max="60000" required></label><label>默认结果数<input v-model.number="settings.defaultCount" type="number" min="1" :max="settings.maxCount" required></label><label>最大结果数<input v-model.number="settings.maxCount" type="number" min="1" :max="settings.provider==='deepseek'?50:20" required></label><label>正文最多字符<input v-model.number="settings.maxContentChars" type="number" min="100" max="50000" required></label></div><p class="muted">密钥状态（已保存配置）：{{ configured ? '已配置' : '尚未配置' }}。在管理设置的密钥库写入与引用同名的密钥，或设置服务环境变量；不会展示密钥正文。</p><p class="muted">在 Agent 的「资源与工具」中装配 web_search{{settings.provider==='brave'?'':'、web_fetch'}}。DeepSeek 另提供 deepseek_search / deepseek_fetch。同样遵守当前发送者权限和工具白名单。搜索结果带来源地址，网页正文按上限截断。</p><p v-if="settings.provider==='deepseek'" class="muted">使用本地 AstrBotX 相同的 /v1/tools/search 和 /v1/tools/fetch 协议，需要具有这些工具接口权限的独立密钥。</p><button type="submit" :disabled="busy || !dirty">{{ busy ? '保存中…' : '保存搜索配置' }}</button></fieldset></form></section></template>

<style scoped>.search-fields{display:grid;gap:16px;border:0;padding:0;margin:0;min-width:0}</style>
